import{_ as a,c as i,o as e,b0 as n}from"./chunks/framework.BWMBvyU7.js";const t="/programming-docs/assets/1051302C3-0-1777982581743-37.B7LaYYjg.jpg",p="/programming-docs/assets/105130I43-1-1777982592582-39.B_dnv40w.jpg",l="/programming-docs/assets/1051304219-2-1777982606581-41.-eYDmW1P.png",r="/programming-docs/assets/105130BE-3-1777982628268-43.CijlxUz-.png",b=JSON.parse('{"title":"LV590-栈和栈溢出","description":null,"frontmatter":{"title":"LV590-栈和栈溢出","date":"2026-05-05T20:01:45.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/Language/c/memory/126d4437261110d7b79d0dab","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-05-05T20:01:45.269Z","fulluuid":"7b79d0dab54b404db1dfc66765ba5d75","useduuid":"7b79d0dab"}},"headers":[],"relativePath":"sdoc/Language/c/memory/126d4437261110d7b79d0dab.md","filePath":"sdoc/01-编程语言/01-C语言/30-内存管理/LV590-栈和栈溢出.md","lastUpdated":1777987950000}'),o={name:"sdoc/Language/c/memory/126d4437261110d7b79d0dab.md"};function d(h,s,c,k,g,m){return e(),i("div",null,[...s[0]||(s[0]=[n('<h1 id="lv590-栈和栈溢出" tabindex="-1">LV590-栈和栈溢出 <a class="header-anchor" href="#lv590-栈和栈溢出" aria-label="Permalink to &quot;LV590-栈和栈溢出&quot;">​</a></h1><h2 id="一、-栈的基本概念" tabindex="-1">一、 栈的基本概念 <a class="header-anchor" href="#一、-栈的基本概念" aria-label="Permalink to &quot;一、 栈的基本概念&quot;">​</a></h2><p>在《<a href="/programming-docs/sdoc/Language/c/memory/126d4437116439190e88b647.html">01-编程语言\\01-C语言/30-内存管理/LV560-Linux下C程序内存布局.md</a>》中我们讲到，程序的虚拟地址空间分为多个区域，<strong>栈（Stack）</strong> 是其中地址较高的一个区域。<strong>栈（Stack）可以存放函数参数、局部变量、局部数组等作用范围在函数内部的数据，它的用途就是完成函数的调用</strong>。</p><p>栈内存由系统自动分配和释放：发生函数调用时就为函数运行时用到的数据分配内存，函数调用结束后就将之前分配的内存全部销毁。所以局部变量、参数只在当前函数中有效，不能传递到函数外部。</p><h2 id="二、-栈的工作原理" tabindex="-1">二、 栈的工作原理 <a class="header-anchor" href="#二、-栈的工作原理" aria-label="Permalink to &quot;二、 栈的工作原理&quot;">​</a></h2><p>在计算机中，栈可以理解为一个特殊的容器，用户可以将数据依次放入栈中，然后再将数据按照相反的顺序从栈中取出。也就是说，先放入的数据最后才能取出，而最后放入的数据必须先取出。这称为**先进后出（First In Last Out）**原则。</p><p>放入数据常称为入栈或压栈（Push），取出数据常称为出栈或弹出（Pop）。如下图所示：</p><p><img src="'+t+'" alt="数据的出栈和入栈"></p><p>图：数据的出栈和入栈</p><p>可以发现，栈底始终不动，出栈入栈只是在移动栈顶，当栈中没有数据时，栈顶和栈底重合。</p><p>从本质上来讲，栈是一段连续的内存，需要同时记录栈底和栈顶，才能对当前的栈进行定位。在现代计算机中，通常使用 <code>ebp</code> 寄存器指向栈底，而使用 <code>esp</code> 寄存器指向栈顶。随着数据的进栈出栈，esp 的值会不断变化，进栈时 esp 的值减小，出栈时 esp 的值增大。</p><blockquote><p>ebp 和 esp 都是 CPU 中的寄存器：ebp 是 Extend Base Pointer 的缩写，通常用来指向栈底；esp 是 Extend Stack Pointer 的缩写，通常用来指向栈顶。</p></blockquote><p>如下图所示是一个栈的实例：</p><p><img src="'+p+'" alt="栈实例"></p><h2 id="三、-栈的大小以及栈溢出" tabindex="-1">三、 栈的大小以及栈溢出 <a class="header-anchor" href="#三、-栈的大小以及栈溢出" aria-label="Permalink to &quot;三、 栈的大小以及栈溢出&quot;">​</a></h2><p>对每个程序来说，栈能使用的内存是有限的，一般是 1M~8M，这在编译时就已经决定了，程序运行期间不能再改变。如果程序使用的栈内存超出最大值，就会发生**栈溢出（Stack Overflow）**错误。</p><blockquote><p>一个程序可以包含多个线程，每个线程都有自己的栈，严格来说，栈的最大值是针对线程来说的，而不是针对程序。</p></blockquote><p>栈内存的大小和编译器有关，编译器会为栈内存指定一个最大值，在 VC/VS 下，默认是 1M，在 C-Free 下，默认是 2M，在 Linux GCC 下，默认是 8M。</p><p>当然，我们也可以通过参数来修改栈内存的大小。以 VS2010 为例，在工程名处右击，会弹出一个菜单，选择&quot;属性&quot;，会出现一个对话框，如下图所示：</p><p><img src="'+l+`" alt="VS2010设置栈大小"></p><p>该图中，我们将栈内存设置为 4M。提示：栈也经常被称为<strong>堆栈</strong>，而堆依然称为堆，所以堆栈这个概念并不包含堆，要注意区分。</p><p>当程序使用的栈内存大于默认值（或者修改后的值）时，就会发生**栈溢出（Stack Overflow）**错误。使用 VS2010 并切换到 Debug 模式，运行如下的代码：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> main</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(){</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    char</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> str</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1024</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1024</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>局部字符数组 str 存储在栈上，占用 2M 的内存，超出了默认值 1M，所以会发生栈溢出错误，如下图所示：</p><p><img src="`+r+'" alt="栈溢出错误"></p><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>',27)])])}const _=a(o,[["render",d]]);export{b as __pageData,_ as default};
